async(page)=>{
 const checks=[],base='E:/Dr.RouteFit/prototype/records/2026-10-24-distance-pricing/';const assert=(ok,msg)=>{if(!ok)throw Error(msg)};
 const role=async r=>{await page.locator(`[data-role=${r}]`).first().click();if(r==='dispatch')await page.locator('[data-dispatch-tab=orders]').click()};
 const open=async a=>page.locator(`[data-action=${a}]`).first().click();
 const fill=async p=>{for(const [k,v]of Object.entries(p)){const el=page.locator(`#action-form [name=${k}]`);if(k==='vehicle'){await page.locator(`[name=vehicle][value=${v}]`).check();continue;}if(typeof v==='boolean')await el.setChecked(v);else if(await el.evaluate(x=>x.tagName)==='SELECT')await el.selectOption(String(v));else await el.fill(String(v))}};
 const submit=async()=>{await page.locator('#action-form [type=submit]').click();await page.locator('#dialog').waitFor({state:'hidden',timeout:4000})};const act=async(a,p={})=>{await open(a);await fill(p);await submit()};
 const close=async()=>{await page.locator('[data-close]').first().click();if(await page.locator('#dialog').isVisible())await page.locator('[data-close]').first().click()};
 const error=async text=>{await page.locator('#action-form [type=submit]').click();await page.waitForFunction(t=>document.querySelector('#form-error')?.textContent.includes(t),text)};
 const state=()=>page.evaluate(()=>JSON.parse(sessionStorage.getItem('routefit-r1-prototype-v1')));
 await page.goto('http://127.0.0.1:4173/prototype/');await page.reload();await page.setViewportSize({width:1440,height:1000});await role('dispatch');await open('qa');await act('reset');await role('dispatch');
 const future=new Date(Date.now()+8*3600000).toISOString().slice(0,16);
 await act('create',{customer:'演示超距客户',destination:'演示远距离收货点',cargo:'包装纸箱',qty:1,weight:10,length:20,width:20,height:20,amount:10,serviceType:'flash',flashFee:3,commissionPercent:20,quoteMode:'distance',entrance:'东门货物入口',distanceKm:12.5,includedKm:10,maxKm:30,perKm:2,distanceRounding:'actual',areaStatus:'pending',distanceEvidence:'DEMO-ROAD-12.5 / DEMO-RATE-2',quoteValidUntil:future});
 let db=await state();const id=db.orders[0].id;assert(db.orders[0].amountMinor===1800,'distance surcharge omitted');
 await open('promise');await fill({basis:'DEMO资源核对',address:true,measured:true,confirmed:true,exclusive:true,flashConfirmed:true,distanceConfirmed:true});await error('区域');await close();checks.push('地址区域待核验阻断承诺，付费不绕过服务准入');
 await act('edit',{areaStatus:'approved',destination:'演示远距离收货点 B',distanceKm:12.5});await open('promise');assert((await page.locator('#action-form').innerText()).includes('超出 2.5 km'),'breakdown absent');await fill({basis:'DEMO资源核对',address:true,measured:true,confirmed:true,exclusive:true,flashConfirmed:true});await error('客户');await fill({distanceConfirmed:true});await page.screenshot({path:base+'quote-confirmation.png',fullPage:true});await submit();checks.push('草稿改地址重新计价、基础10+超距5+闪送3=18，单独确认客户加价');
 await act('offer',{vehicle:'V01'});await role('driver');await act('accept');await role('warehouse');await act('prepare',{dimension:true,pattern:true,packaging:true,evidence:'DEMO-LOAD'});await role('driver');await act('pickup',{evidence:'DEMO-HO'});await act('depart');await page.setViewportSize({width:390,height:844});assert(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth),'mobile overflow');assert((await page.locator('main').innerText()).includes('超出 2.5 km'),'driver missing fee breakdown');await page.screenshot({path:base+'driver-distance.png',fullPage:true});await act('report',{proof:'DEMO-CASH'});await act('deliver',{receiver:'演示收货人',evidence:'DEMO-POD'});await page.setViewportSize({width:1440,height:1000});await role('finance');await act('verify',{evidence:'DEMO-COUNT'});await role('driver');await act('remit',{evidence:'DEMO-REMIT'});await role('finance');await act('reconcile',{evidence:'DEMO-RECON'});await page.locator('[data-backend-tab=details]').click();await page.locator('[data-tab=finance]').click();assert((await page.locator('.detail-body').innerText()).includes('USD 18.00'),'finance total inconsistent');await page.screenshot({path:base+'finance-distance.png',fullPage:true});
 await page.locator('[data-nav=pricing]').click();await page.locator('[data-section-tab=orders]').click();await page.locator(`[data-resource="${id}"]`).click();await act('earningPost',{evidence:'DEMO-SPLIT'});db=await state();assert(db.earnings[0].totalMinor===1800&&db.earnings[0].driverMinor===1440&&db.earnings[0].platformMinor===360,'distance split inconsistent');checks.push('司机查看里程费用、18美元收款与核验、20%示例分成按完整运费入账');
 await page.reload();assert((await state()).orders.find(o=>o.id===id).distanceQuote.confirmedAt,'quote snapshot lost on reload');checks.push('390px布局与刷新后的报价快照保留');return {status:'PASS',checks};
}
